import{z as o,x as s,o as A,c as d,q as r,j as n,D as e,d as t,s as l,S as i,b as a}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"申赎与套利机制","description":"","frontmatter":{"title":"申赎与套利机制","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/etf-create-redeem-arb.md","filePath":"quant/etf-create-redeem-arb.md","lastUpdated":1791413859000}'),F={name:"quant/etf-create-redeem-arb.md"};function C(p,E,D,m,P,f){const B=s("Mermaid");return A(),d("div",null,[E[2]||(E[2]=r('<h1 id="申赎与套利机制" tabindex="-1">申赎与套利机制 <a class="header-anchor" href="#申赎与套利机制" aria-label="Permalink to &quot;申赎与套利机制&quot;">​</a></h1><div class="epigraph"><p>ETF 的价格纪律不是交易所给的，而是那一篮子随时可以换进换出的股票给的：申赎管道开多宽，折溢价就只能走多远。</p><footer>—— 据 ETF 发行人说明书与交易所申赎细则整理；证据见 Petajisto, Financial Analysts Journal, 2017</footer></div><p><a href="/quant/etf-index-construction">上一课</a>把指数写成一份工程规格：样本、权重因子、缓冲带与日历。缺口是规格只有变成份额的供给，二级市场的价格才被钉住。本课写规则到份额的接口：申购赎回清单（PCF）、盘中参考净值（IOPV）、创建赎回与套利带。授权参与商的资产负债表与失败交割细节见<a href="/quant/etf-create-redeem">ETF 创建赎回套利</a>，A 股申赎细则见<a href="/quant/cn-etf-creation">ETF 申赎与 IOPV</a>，定价效率的证据见<a href="/quant/etf-arb">ETF 与成分股</a>；本课程的角度是机制——申赎如何把指数规则翻译成供给弹性。后课都默认这条管道在。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>记折溢价 \\(D = P/V - 1\\)，\\(P\\) 是二级市场价格，\\(V\\) 是此刻可成交的篮子价值。缺口在于 \\(D\\) 的分子好算、分母难算：会计 NAV 按最近成交价计，停牌与涨跌停的成分没有可买价；IOPV 实时但同样陈旧。可执行的公平价值只能是自建篮子：按 PCF 逐腿用可成交报价计价，再加费用带。于是问题变成：套利带的四壁各有多厚——篮子执行成本、申赎费用与最小单位、现金替代的不确定性、结算时滞。</p><p><span class="marginnote">数字实例：宽基股票 ETF 的四壁若是滑点 3bp、申赎费 1bp、现金替代折扣 2bp、隔夜资金 1bp，带宽约 7bp；跨境或债券产品同样的四壁可能是 30+10+20+10=70bp。同样看到「偏离 0.5%」，在前者是肥肉，在后者可能只是口径差。</span></p><p>PCF 是指数规则的衍生品：正常情况下按基金实际持仓给出（复制偏离使它不等于指数权重），停牌、外资受限的成分折成现金替代条目，事前收、事后退补。读不懂上一课的权重规则，就读不出哪些条目是例行、哪些是管道收窄的信号。</p>',7)),(A(),n(i,null,{default:e(()=>[l(B,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20HOLD%5B%22%E5%9F%BA%E9%87%91%E5%AE%9E%E9%99%85%E6%8C%81%E4%BB%93%22%5D%20--%3E%20NAV%5B%22%E4%BC%9A%E8%AE%A1%20NAV%3A%20%E6%8C%89%E6%9C%80%E8%BF%91%E6%88%90%E4%BA%A4%E4%BB%B7%22%5D%0A%20%20NAV%20--%3E%20OLD%5B%22%E5%81%9C%E7%89%8C%E4%B8%8E%E6%B6%A8%E8%B7%8C%E5%81%9C%E6%88%90%E5%88%86%E6%8A%A5%E4%BB%B7%E9%99%88%E6%97%A7%22%5D%0A%20%20PCF%5B%22%E7%94%B3%E8%B5%8E%E6%B8%85%E5%8D%95%20PCF%22%5D%20--%3E%20EST%5B%22%E8%87%AA%E5%BB%BA%E7%AF%AE%E5%AD%90%3A%20%E9%80%90%E8%85%BF%E5%8F%AF%E6%88%90%E4%BA%A4%E6%8A%A5%E4%BB%B7%22%5D%0A%20%20EST%20--%3E%20V%5B%22%E5%8F%AF%E6%89%A7%E8%A1%8C%E5%85%AC%E5%B9%B3%E4%BB%B7%E5%80%BC%20V%22%5D%0A%20%20FEES%5B%22%E8%B4%B9%E7%94%A8%E5%B8%A6%3A%20%E6%BB%91%E7%82%B9%2B%E7%94%B3%E8%B5%8E%E8%B4%B9%2B%E7%8E%B0%E9%87%91%E6%9B%BF%E4%BB%A3%22%5D%20--%3E%20V%0A%20%20IOPV%5B%22IOPV%22%5D%20-.-%3E%7C%22%E5%8F%82%E8%80%83%E9%94%9A%2C%20%E9%9D%9E%E6%88%90%E4%BA%A4%E4%BB%B7%22%7C%20V%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"方法",tabindex:"-1"},[t("方法 "),a("a",{class:"header-anchor",href:"#方法","aria-label":'Permalink to "方法"'},"​")],-1)),E[4]||(E[4]=a("p",null,"套利动作是两腿的：溢价时买篮子、交信托、换份额、卖 ETF；折价时反向。触发条件是 \\(|D| \\gt b\\)，带宽 \\(b\\) 是四壁之和：篮子的滑点、申赎费、现金替代的保守折扣、资金占用与结算隔夜风险。\\(b\\) 由最厚的一壁决定：成分流动性好的宽基股票 ETF，\\(b\\) 可以小到几个基点；债券、跨境与小众产品，\\(b\\) 宽一个数量级。IOPV 的角色是参考锚：它让带内的偏离可见，但用 IOPV 当 \\(V\\) 去算套利，会在停牌与跨时区成分上把噪声当信号。",-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"跨境 ETF 是带宽的极端样本：底层闭市时 \\(V\\) 只能按隔夜收盘加汇率折算，日内的 \\(D\\) 主要是口径而非错误定价；QDII 额度使申购随时可停，折溢价可以长期停在带外。用国内宽基 ETF 的紧盯去外推，会把口径差当套利空间。")],-1)),(A(),n(i,null,{default:e(()=>[l(B,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20OBS%5B%22%E8%A7%82%E5%AF%9F%20D%20%3D%20P%2FV%20-%201%22%5D%20--%3E%20BAND%7B%22%7CD%7C%20%E8%B6%85%E8%BF%87%E5%B8%A6%E5%AE%BD%20b%3F%22%7D%0A%20%20BAND%20--%3E%7C%E5%90%A6%7C%20IDLE%5B%22%E5%B8%A6%E5%86%85%E5%99%AA%E5%A3%B0%EF%BC%9A%E4%B8%8D%E5%8A%A8%22%5D%0A%20%20BAND%20--%3E%7C%E6%98%AF%7C%20CHECK%7B%22%E7%AF%AE%E5%AD%90%E5%8F%AF%E5%AE%8C%E6%95%B4%E5%A4%8D%E5%88%B6%E4%B8%8E%E4%BA%A4%E5%89%B2%3F%22%7D%0A%20%20CHECK%20--%3E%7C%E5%90%A6%7C%20NARROW%5B%22%E7%AE%A1%E9%81%93%E6%94%B6%E7%AA%84%EF%BC%9A%E4%BB%85%E5%B0%8F%E4%BB%93%E8%AF%95%E6%8E%A2%22%5D%0A%20%20CHECK%20--%3E%7C%E6%98%AF%7C%20PREM%7B%22D%20%E4%B8%BA%E6%AD%A3%3F%22%7D%0A%20%20PREM%20--%3E%7C%E6%98%AF%7C%20CREATE%5B%22%E4%B9%B0%E7%AF%AE%E5%AD%90%E3%80%81%E7%94%B3%E8%B4%AD%E3%80%81%E5%8D%96%20ETF%22%5D%0A%20%20PREM%20--%3E%7C%E5%90%A6%7C%20REDEEM%5B%22%E4%B9%B0%20ETF%E3%80%81%E8%B5%8E%E5%9B%9E%E3%80%81%E5%8D%96%E7%AF%AE%E5%AD%90%22%5D%0A%20%20CREATE%20--%3E%20CLOSE%5B%22%E4%BB%B7%E6%A0%BC%E5%9B%9E%E5%88%B0%E5%B8%A6%E5%AE%BD%E5%86%85%22%5D%0A%20%20REDEEM%20--%3E%20CLOSE%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>申赎把封闭式基金的固定份额变成有供给弹性的份额：带内的折溢价无人去收，因为它收不回成本；带外的偏离召唤 AP 开工，价格被拉回。纪律不在「套利者勤奋」，而在管道畅通——四壁中任何一壁加厚（停牌增多、现金替代比例上升、申赎暂停），带宽就变宽，纪律就变松。极端情形管道关死，ETF 退化成封闭式基金，折溢价不再收敛。</p><p><span class="marginnote">直觉类比：申赎管道像蓄水池的进出水管。带内折溢价是水面的小涟漪，没人管；带外偏离相当于水位超出水管口径，AP 立刻开闸把水位压回去。四壁加厚等于水管变细，水面波动更猛；管道焊死，ETF 就成了一口封死的缸（封闭式基金）。</span></p><p>这条机制把上一课与后课连起来：规则可预测，所以 PCF 的变化（现金替代条目增多）在生效前就预告申赎行为与被动需求；跟踪误差课要写的估值噪声，正是带宽内侧「看不见的交易」的痕迹。套利本身也有容量：AP 的资本、融资与交割额度是有限的，\\(D\\) 持续偏大时先到者收走带外部分，后来者挤进带内——把历史偏离分布当成未来套利收益表，会高估可分到的份额。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 AP 的做空渠道与失败交割细节，见<a href="/quant/etf-create-redeem">ETF 创建赎回套利</a>；A 股单市场产品的回转安排与跨市场产品的 T+1 差异，见<a href="/quant/cn-etf-creation">ETF 申赎与 IOPV</a>，它们改变的是结算壁的厚度。二级市场交易把冲击传回成分股的证据见<a href="/quant/etf-arb">ETF 与成分股</a>。也不把套利带写成常数：它随市场状态、申赎开放状态与成分事件实时变化，任何回测都应把 \\(b\\) 当状态变量而不是参数。</p><p><span class="marginnote">常见误区：把历史折溢价的分布当成未来的套利收益表。带外偏离会被先到的 AP 收走，你统计出的尾部早就是别人的利润；再把带宽设成常数回测，就双重高估了可执行机会。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>申赎管道把份额供给弹性化，折溢价被压在带宽 \\(b\\) 内；\\(b\\) 由篮子滑点、申赎费用、现金替代与结算四壁中最厚的一壁决定。</li><li>可执行的 \\(V\\) 是自建篮子，不是会计 NAV；IOPV 是参考锚，跨时区与停牌成分上是口径而非价格。</li><li>PCF 是指数规则的衍生品，现金替代条目是管道收窄的先行信号。</li><li>管道关死时 ETF 退化为封闭式基金；套利容量受 AP 资本与额度约束。</li><li>出处：Petajisto, <em>Financial Analysts Journal</em>, 2017；Marshall, Nguyen and Visaltanachoti, <em>Journal of Banking &amp; Finance</em>, 2013；机制口径据发行人说明书与沪深交易所申赎细则整理。</li></ul>',9))])}const b=o(F,[["render",C]]);export{T as __pageData,b as default};
